# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, Iterable, List

from hourglass.models import Shift

MINUTES_PER_HOUR = 60

# ---
def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, like Brisa: 3 shifts, 9.0 hours.

    Busiest first: most hours, then most shifts, then name.
    Overlaps for the same worker are counted, as in
    worker_minutes. ValueError for no shifts at all or for
    a shift whose worker name is blank.
    """
    counts: Dict[str, int] = {}
    totals: Dict[str, int] = {}
    for shift in shifts:
        name = shift.worker.strip()
        if not name:
            raise ValueError("blank worker name")
        counts[name] = counts.get(name, 0) + 1
        minutes = shift.span.minutes
        totals[name] = totals.get(name, 0) + minutes
    if not totals:
        raise ValueError("no shifts given")

    def busiest(name: str):
        return (-totals[name], -counts[name], name)

    return [
        _format_line(name, counts[name], totals[name])
        for name in sorted(totals, key=busiest)
    ]

def _format_line(name: str, count: int, mins: int) -> str:
    noun = "shift" if count == 1 else "shifts"
    hours = mins / MINUTES_PER_HOUR
    return f"{name}: {count} {noun}, {hours:.1f} hours"
